package com.finflow.payment; import org.slf4j.MDC; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.client.RestClient; import java.math.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*;
@Service class PaymentService{private final PaymentRepository payments;private final OutboxRepository outbox;private final RestClient account;private final RestClient fraud;PaymentService(PaymentRepository p,OutboxRepository o,@Value("${clients.account-url}")String au,@Value("${clients.fraud-url}")String fu){payments=p;outbox=o;account=RestClient.create(au);fraud=RestClient.create(fu);} record Cmd(UUID sourceAccountId,UUID destinationAccountId,BigDecimal amount,String currency){} record View(UUID paymentId,String status){}
@Transactional View create(String key,Cmd c){String hash=hash(c.toString());var old=payments.findByIdempotencyKey(key);if(old.isPresent()){if(!old.get().requestHash.equals(hash))throw new IllegalArgumentException("Idempotency key reused with different request");return new View(old.get().id,old.get().status);}var p=Payment.create(key,hash,c.sourceAccountId,c.destinationAccountId,c.amount,c.currency,MDC.get("correlationId"));payments.save(p);Map<?,?> decision=fraud.post().uri("/api/v1/fraud/evaluate").body(Map.of("amount",c.amount,"customerId","demo")).retrieve().body(Map.class);if("REVIEW".equals(decision.get("decision"))){p.status("REVIEW_REQUIRED");outbox.save(OutboxEvent.of(p.id,"payment.review-required",json(p)));return new View(p.id,p.status);}account.post().uri("/api/v1/accounts/internal/post").body(Map.of("sourceAccountId",c.sourceAccountId,"destinationAccountId",c.destinationAccountId,"amount",c.amount)).retrieve().toBodilessEntity();p.status("POSTED");outbox.save(OutboxEvent.of(p.id,"payment.completed.v1",json(p)));return new View(p.id,p.status);}Payment get(UUID id){return payments.findById(id).orElseThrow();}private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private static String json(Payment p){return "{\"paymentId\":\""+p.id+"\",\"status\":\""+p.status+"\"}";}}
